from sqlalchemy import (
    Column, ForeignKey, Integer, MetaData, String, Table, create_engine, func, select,
)
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker

metadata = MetaData()

authors = Table(
    "authors", metadata,
    Column("id", Integer, primary_key=True),
    Column("name", String(50), nullable=False),
)

Base = declarative_base(metadata=metadata)


class Book(Base):
    __tablename__ = "books"

    id = Column(Integer, primary_key=True)
    title = Column(String(80), nullable=False)
    pages = Column(Integer, default=0)
    author_id = Column(Integer, ForeignKey("authors.id"))


def make_engine():
    engine = create_engine("sqlite://")
    metadata.create_all(engine)
    return engine


def add_author(engine, name):
    result = engine.execute(authors.insert(), name=name)
    return result.inserted_primary_key[0]


def author_names(engine):
    query = select([authors.c.name]).order_by(authors.c.id)
    return engine.execute(query).fetchall()


def author_row(engine, author_id):
    query = select([authors]).where(authors.c.id == author_id)
    return engine.execute(query).first()


def author_name(engine, author_id):
    row = author_row(engine, author_id)
    return row["name"]


def author_dict(engine, author_id):
    return dict(author_row(engine, author_id))


def add_books(engine, author_id, titles):
    Session = sessionmaker(bind=engine)
    session = Session()
    for i, title in enumerate(titles):
        session.add(Book(title=title, pages=100 * (i + 1), author_id=author_id))
    session.commit()
    session.close()


def get_book(engine, book_id):
    session = sessionmaker(bind=engine)()
    try:
        book = session.query(Book).get(book_id)
        return book.title if book is not None else None
    finally:
        session.close()


def book_count(engine):
    with engine.connect() as conn:
        return conn.execute("SELECT COUNT(*) FROM books").scalar()


def pages_by_author(engine):
    query = (
        select([authors.c.name, func.sum(Book.__table__.c.pages).label("total")])
        .select_from(authors.join(Book.__table__, Book.__table__.c.author_id == authors.c.id))
        .group_by(authors.c.name)
    )
    return engine.execute(query).fetchall()


def table_names(engine):
    return sorted(engine.table_names())


def reflected_tables(engine):
    meta = MetaData(bind=engine)
    meta.reflect()
    return sorted(meta.tables)

